    10	  formatRating,
    11	} from "@/lib/parks/format";
    12	
    13	/*
    14	 * Opt out of Next.js's "instant navigation" check for this route. Passing it
    15	 * would mean reading `params` inside <Suspense>, and calling notFound() there
    16	 * sends a 200 "soft 404" for unknown parks. Every real park page is
    17	 * prerendered at build time anyway, so nothing here is slow to wait for.
    18	 */
    19	export const instant = false;
    20	
    21	export function generateStaticParams() {
    22	  return getParks().map((park) => ({ id: park.id }));
    23	}
    24	
    25	export async function generateMetadata({
    26	  params,
    27	}: PageProps<"/parks/[id]">): Promise<Metadata> {
    28	  const { id } = await params;
    29	  const park = getPark(id);
    30	  if (!park) return { title: "Park not found" };
    31	  return {
    32	    title: park.name,
    33	    description:
    34	      park.description ?? `Hours, amenities and directions for ${park.name}.`,
    35	  };
    36	}
    37	
    38	export default async function ParkPage({ params }: PageProps<"/parks/[id]">) {
    39	  const { id } = await params;
    40	  const park = getPark(id);
    41	  // Checked before anything renders so unknown ids get a real 404 status.
    42	  if (!park) notFound();
    43	
    44	  return (
    45	    <article className="mx-auto flex w-full max-w-5xl flex-col gap-6 px-4 py-6 sm:px-6">
    46	      <nav aria-label="Breadcrumb">
    47	        <Link
    48	          href="/"
    49	          className="inline-flex min-h-11 items-center gap-1 rounded-md font-medium text-accent hover:text-accent-hover hover:underline"
    50	        >
    51	          <span aria-hidden="true">←</span> All parks
    52	        </Link>
    53	      </nav>
    54	
    55	      <header className="flex flex-col gap-1">
    56	        <h1 className="text-3xl font-bold tracking-tight sm:text-4xl">
    57	          {park.name}
    58	        </h1>
    59	        {park.address && <p className="text-lg text-muted">{park.address}</p>}
    60	      </header>
    61	
    62	      {/* Visit info comes first in reading order (and first on phones), since
    63	          hours and directions are what most residents need. On wide screens
    64	          it sits in the right-hand column. */}
    65	      <div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_20rem] lg:items-start lg:gap-6">
    66	        <aside
    67	          aria-labelledby="visit-heading"
    68	          className="flex flex-col gap-4 rounded-lg border border-border bg-surface p-5 lg:sticky lg:top-4 lg:col-start-2 lg:row-start-1"
    69	        >
    70	          <h2 id="visit-heading" className="text-lg font-semibold">
    71	            Plan your visit
    72	          </h2>
    73	          <dl className="flex flex-col gap-3">
    74	            <Fact label="Hours" value={park.hours} />
    75	            <Fact label="Address" value={park.address} />
    76	            <Fact
    77	              label="Size"
    78	              value={park.acreage !== null ? formatAcreage(park.acreage) : null}
    79	            />
    80	            <Fact
    81	              label="Rating"
    82	              value={park.rating !== null ? formatRating(park.rating) : null}
    83	            />
    84	          </dl>
    85	          {park.coordinates ? (
    86	            <a
    87	              href={directionsUrl(park.coordinates.lat, park.coordinates.lng)}
    88	              target="_blank"
    89	              rel="noopener noreferrer"
    90	              className="inline-flex min-h-11 items-center justify-center gap-2 rounded-md bg-accent px-4 font-semibold text-on-accent hover:bg-accent-hover"
    91	            >
