    93	              <ExternalIcon />
    94	              <span className="sr-only">(opens Google Maps in a new tab)</span>
    95	            </a>
    96	          ) : (
    97	            <NotListed>
    98	              Directions aren’t available because this park’s location isn’t
    99	              listed.
   100	            </NotListed>
   101	          )}
   102	        </aside>
   103	        <div className="flex flex-col gap-8 lg:col-start-1 lg:row-start-1">
   104	          <Section title="About">
   105	            {park.description ? (
   106	              <p className="max-w-prose leading-relaxed">{park.description}</p>
   107	            ) : (
   108	              <NotListed>No description available.</NotListed>
   109	            )}
   110	          </Section>
   111	
   112	          <Section title="Amenities">
   113	            {park.amenities.length > 0 ? (
   114	              <ul className="flex flex-wrap gap-2">
   115	                {park.amenities.map((amenity) => (
   116	                  <li
   117	                    key={amenity}
   118	                    className="rounded-full border border-border bg-surface px-3 py-1 text-sm font-medium"
   119	                  >
   120	                    {amenityLabel(amenity)}
   121	                  </li>
   122	                ))}
   123	              </ul>
   124	            ) : (
   125	              <NotListed>No amenities listed.</NotListed>
   126	            )}
   127	          </Section>
   128	
